action.code:
size_t nbits = binfo->nbits;
size_t ngroups = BITMAP_GROUPS_L0(nbits);
size_t trailing_bits = nbits % BITMAP_GROUP_NBITS;
size_t limit = (trailing_bits == 0 ? ngroups : ngroups - 1);

for (size_t i = 0; i < limit; i++) {
    if (bitmap[i] != ~(bitmap_t)0) {
        return false;
    }
}

if (trailing_bits == 0) {
    return true;
}

bitmap_t mask = ((bitmap_t)1 << trailing_bits) - 1;
return (bitmap[ngroups - 1] & mask) == mask;

